insert into public.keywords (keyword, alias_of, action, message, message_source, question, target_type, target, voicemail_note, notes) values
  ('Accounts Payable', null, 'transfer', null, 'script', null, 'extension', '187', true, 'Vendor calling about a bill/invoice issued to MVCAP or a check issued by MVCAP -> Caseam Pleasant'),
  ('Attorney', null, 'transfer', null, 'script', null, 'extension', '157', true, 'Attorney or legal representative'),
  ('Elected Official', null, 'transfer', null, 'script', null, 'extension', '157', true, 'Local, state, or federal elected officials'),
  ('Emergency Responders', null, 'transfer', null, 'script', null, 'extension', '157', true, 'Police, law enforcement, emergency responders'),
  ('Leadership Team', null, 'transfer', null, 'script', null, 'extension', '157', true, null),
  ('Finance', null, 'transfer', null, 'script', null, 'extension', '157', false, 'CFO or a financial request'),
  ('Clothing Bank', null, 'transfer', null, 'script', null, 'extension', '601', false, 'Darke County Clothing Bank is closed (status update 9/1/2026)'),
  ('Housing and Financial Counseling', null, 'transfer', null, 'script', null, 'extension', '172', false, null),
  ('Furnace', null, 'transfer', null, 'script', null, 'extension', '226', false, 'Weatherization and Housing Services'),
  ('Donnellan Shelter', null, 'transfer', null, 'script', null, 'phone', '+19373763111', false, 'Rings all case managers at the shelter'),
  ('Domestic Violence', null, 'transfer', null, 'script', null, 'phone', '+19374566891', false, 'SAFETY-CRITICAL. Domestic Violence Services hotline'),
  ('Monitoring', null, 'transfer', null, 'script', null, 'extension', '171', false, 'Funder/grantmaker about an upcoming monitoring visit -> Kevin Reeves'),
  ('Weatherization', null, 'say_transfer', 'Please allow me to transfer you to the Weatherization and Housing Services Team.', 'script', null, 'extension', '226', false, null),
  ('Darke County', null, 'say_transfer', 'You can visit our website to learn more about the programs we offer to Darke County Residents. Visit www.miamivalleycap.org, click Counties, then click Darke County Services. I''ll transfer you to their office now.', 'script', null, 'extension', '601', false, null),
  ('Greene County', null, 'say_transfer', 'You can visit our website to learn more about the programs we offer to Greene County Residents. Visit www.miamivalleycap.org, click Counties, then click Greene County Services. I''ll transfer you to their office now.', 'script', null, 'extension', '601', false, 'CONFIRM WITH CLIENT: script says x601, which is a Darke County extension'),
  ('Preble County', null, 'say_transfer', 'You can visit our website to learn more about the programs we offer to Preble County Residents. Visit www.miamivalleycap.org, click Counties, then click Preble County Services. I''ll transfer you to their office now.', 'script', null, 'extension', '501', false, null),
  ('Darke County MHA', null, 'say_transfer', 'MVCAP administers the MHA program in Darke County through a management agreement with the Darke County MHA Board of Commissioners.', 'script', null, 'extension', '601', false, null),
  ('Preble MHA', null, 'say_transfer', 'MVCAP administers the MHA program in Preble County through a management agreement with the Preble MHA Board of Commissioners.', 'script', null, 'extension', '501', false, null),
  ('AES', null, 'refer', 'For that request, please call AES directly at 800-433-8500.', 'drafted', null, null, null, false, 'Script: refer caller directly to AES'),
  ('National Fuel', null, 'refer', 'For that request, please call National Fuel directly at 800-838-0933.', 'drafted', null, null, null, false, 'Script: refer caller directly to National Fuel'),
  ('Appeals', null, 'say_end', 'Each MVCAP program has unique appeals processes for denied applications. Please visit our website at www.miamivalleycap.org to learn these processes and timelines for each of our programs. If you need to speak with someone, please email appeals at mvcap dot com.', 'script', null, null, null, false, 'Script says to give appeals@mvcap.com only if they insist. Internal escalation contact is never shared or transferred to.'),
  ('Board of Trustees', null, 'say_end', 'MVCAP''s Board of Trustees information is listed on our website at www.miamivalleycap.org. Click About Us, then click Board of Trustees. You can mail correspondence to Miami Valley Community Action Partnership, attention Board of Trustees, 719 South Main Street, Dayton, Ohio 45402.', 'script', null, null, null, false, null),
  ('Camden Commons', null, 'refer', 'This property is managed by Oberer Property Management. Please dial 937-456-3241.', 'drafted', null, null, null, false, 'Script: managed by Oberer Property Management; direct caller to dial 937-456-3241'),
  ('Fox Run', null, 'refer', 'This property is managed by Oberer Property Management. Please dial 937-316-8025.', 'drafted', null, null, null, false, null),
  ('Employment Inquiries', null, 'say_end', 'MVCAP''s current job openings are posted on our website, www.miamivalleycap.org. Click Support Us, then Careers, then Click Here for Available Job Openings. Applications are accepted through our online portal.', 'script', null, null, null, false, 'Internal escalation contact (never shared, never transferred to) is in the script'),
  ('Human Resources', null, 'say_end', 'Please email your request to H R at mvcap dot com.', 'drafted', null, null, null, false, 'Script: unless they ask for an HR team member by name, ask them to email HR@mvcap.com. Name requests go through the directory.'),
  ('News', null, 'say_end', 'Please email your request to news at mvcap dot com.', 'drafted', null, null, null, false, 'Reporter, journalist, or news outlet'),
  ('Workforce Development', null, 'say_end', 'MVCAP is not offering workforce development programs at this time. Please call United Way HelpLink at 211 for additional resources.', 'drafted', null, null, null, false, 'Script: refer all callers to United Way HelpLink 211'),
  ('Micro Enterprise Program', null, 'followup', 'MVCAP no longer offers this program. Please call United Way HelpLink at 211 for additional resources.', 'script', null, null, null, false, 'Script: then ask the caller additional questions'),
  ('Driver''s License Reinstatement', null, 'followup', 'MVCAP''s Drivers License Reinstatement program is currently paused. Please visit our website for additional information.', 'script', null, null, null, false, 'Script: then ask the caller additional questions'),
  ('Application', null, 'followup', 'Each MVCAP program has unique application processes, eligibility requirements, and documentation requirements. Please visit our website at www.miamivalleycap.org to learn these requirements for each of our programs.', 'script', null, null, null, false, 'Script: then ask additional questions and match other keywords'),
  ('Community Services Block Grant', null, 'followup', 'Could you tell me a little more about what you''re looking for?', 'drafted', null, null, null, false, 'Script: ask additional questions and match other keywords'),
  ('Montgomery County', null, 'followup', 'Could you tell me a little more about what you need help with?', 'drafted', null, null, null, false, 'Script: ask about the nature of the request and match other keywords'),
  ('Grants', null, 'ask', null, 'drafted', 'Are you a funder or grantmaker calling about a grant you''ve given MVCAP, or are you asking about grants MVCAP offers?', null, null, false, 'Script: a client asking if we offer grants -> ask more questions; a funder/grantmaker about a grant given to MVCAP -> Kevin Reeves x171'),
  ('Affordable Housing', null, 'ask', null, 'script', 'MVCAP offers affordable housing in Darke and Preble Counties. Which of the following departments would you like me to transfer you to: Darke County MHA, Preble MHA, Camden Commons, Eagles Nest, Fox Run, or Willow Place?', null, null, false, 'Question wording is the script''s; the department list is added so the caller hears the options'),
  ('Metropolitan Housing Authority', null, 'ask', null, 'drafted', 'MVCAP administers the MHA programs in Darke and Preble Counties through management agreements with those MHA Boards of Commissioners. Which county are you calling about?', null, null, false, 'Question is the script''s statement plus a county question (drafted)'),
  ('Food', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, 'Script: ask what county they live in'),
  ('Clothing Assistance', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, null),
  ('Transportation', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, null),
