  ('Prevention, Retention and Contingency', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, 'Script: ask what county they live in'),
  ('Rental Assistance', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, 'CONFIRM WITH CLIENT: script only defines Montgomery County. Other counties use the PRC county referrals (drafted).'),
  ('Mortgage Assistance', null, 'ask', null, 'script', 'Which county do you live in?', null, null, false, 'CONFIRM WITH CLIENT: script only defines Montgomery County. Other counties use the PRC county referrals (drafted).'),
  ('Utility Assistance', null, 'ask', null, 'script', 'Is your gas or electric service currently disconnected, or have you received a disconnection notice?', null, null, false, 'PIPP uses these prompts; appointments are NOT required for PIPP'),
  ('Summer Crisis', null, 'ask', null, 'script', 'Have you submitted an application for utility assistance since July 1, 2026?', null, null, false, 'Goal: tell them an appointment is required. Appointments for the next three weeks are released every Friday at 4:30 p.m.'),
  ('Winter Crisis', null, 'say_end', 'Please visit our website at www.miamivalleycap.org for more information.', 'drafted', null, null, null, false, 'Script text (''will begin accepting applications Nov 1'') is outdated. The current status update is spoken first. CONFIRM WITH CLIENT.'),
