  ('Utility Assistance', 'yes', 'say_transfer', 'If you haven''t already submitted an application, please apply on our website at www.miamivalleycap.org, click Programs, then click Utility Assistance, then click Apply Online. I''ll transfer you to a member of our utility assistance team. If they are unable to answer, leave a voicemail with your name, phone number, address, and date of disconnection.', 'script', 'extension', '821', null, false, 'x821 is not in the directory; confirm with client'),
  ('Utility Assistance', 'no', 'say_transfer', 'We encourage you to submit an online application through our website at www.miamivalleycap.org, click Programs, then click Utility Assistance, then click Apply Online.', 'script', 'extension', '102', null, false, null),
  ('Summer Crisis', 'yes', 'say_transfer', 'Thank you. An appointment is required for this program. Appointments can be scheduled on our website at www.miamivalleycap.org, click Programs, then click Utility Assistance, then click Montgomery County Residents, Schedule an In-Person Appointment.', 'script', 'phone', '+19375144777', null, false, null),
