insert into public.status_updates (update_date, text, applies_to, active, notes) values
  ('2026-10-29', 'The Darke County Emergency Shelter Program and the Darke County Domestic Violence Services Program reopen on November 1, 2026.', null, false, 'Reopening date has passed; inactive. Confirm it is no longer needed.'),
  ('2026-10-29', 'The 2026-2027 Winter Crisis program is accepting applications from November 1, 2026, through March 31, 2027. An appointment is required. Appointments can be scheduled online through www.miamivalleycap.org or by calling 937-514-4777.', array['Winter Crisis']::text[], true, 'Spoken before the Winter Crisis message'),
  ('2026-09-01', 'The Clothing Bank at the Darke County location is closed until further notice due to required maintenance.', array['Clothing Bank', 'Clothing Assistance']::text[], true, 'Spoken before the clothing routes. CONFIRM whether callers should still be transferred.'),
  ('2026-07-01', 'Utility Assistance: the 2026-2027 Home Energy Assistance Program (HEAP) application is open. Customers are encouraged to submit applications online through www.miamivalleycap.org.', null, true, 'General background for the model; not spoken on its own')
insert into public.settings (key, value, notes) values
  ('greeting', '"Thank you for calling Miami Valley Community Action Partnership. How may I help you?"'::jsonb, 'Script greeting without the agent-name blank. CONFIRM final wording with client.'),
  ('voicemail_note', '"If they are unable to take your call, please leave a detailed voice message."'::jsonb, 'Spoken before transfers that carry the voicemail note'),
  ('default_transfer_message', '"One moment while I transfer you."'::jsonb, 'Spoken before a transfer that has no scripted message'),
  ('fallback_message', '"I''m sorry, I wasn''t able to help with that request. Let me connect you with a team member."'::jsonb, 'PENDING CLIENT: spoken when escalating to a human'),
  ('transfer_failed_message', '"I''m sorry, I wasn''t able to complete that transfer. Please visit www.miamivalleycap.org, or call United Way HelpLink at 211."'::jsonb, 'PENDING CLIENT: spoken when a transfer fails'),
  ('human_fallback_number', null, 'PENDING CLIENT: E.164 number that rings a human, e.g. +19375551234'),
  ('pbx_main_number', null, 'PENDING CLIENT: main office number in E.164. Extension transfers dial this number, wait pbx_dtmf_pause_seconds, then send the extension as keypad tones'),
  ('pbx_dtmf_pause_seconds', '3'::jsonb, 'Seconds to wait after the main number answers before sending the extension'),
  ('transfer_mode', '"bridge"'::jsonb, 'bridge | blind | hybrid. blind hands the caller over and the agent leaves (an extension rides as post-dial digits, which the provider may ignore); hybrid = blind for phone numbers, bridge for extensions'),
  ('transfer_override_number', null, 'TEST SWITCH: when set (E.164), every transfer rings this number instead of the real target. Leave empty in production'),
  ('office_hours_statement', '"Hours of operation are Monday through Friday, 8:00 a.m. to 4:30 p.m., closed for lunch from 12:00 p.m. to 1:00 p.m. Offices are closed for holidays. Visiting hours vary by location."'::jsonb, 'Script wording, spoken by the model only when a caller asks about hours'),
  ('goodbye_message', '"Thank you for calling Miami Valley Community Action Partnership. Goodbye."'::jsonb, 'Drafted by us (the script has none). Spoken when the caller is finished. CONFIRM with client.'),
  ('timezone', '"America/New_York"'::jsonb, null),
  ('office_hours', '{"days": "Mon-Fri", "open": "08:00", "close": "16:30", "lunch_closed": ["12:00", "13:00"]}'::jsonb, 'Closed for holidays. After-hours behavior is PENDING CLIENT.')
